"(function() {
    if (window.__pisanoKeyboardViewportSync) return;
    window.__pisanoKeyboardViewportSync = true;

    function layoutHeightPx() {
        return Math.round(window.innerHeight || 0);
    }

    function visibleHeightPx() {
        if (window.visualViewport && window.visualViewport.height > 0) {
            return Math.round(window.visualViewport.height);
        }
        return layoutHeightPx();
    }

    function isKeyboardOpen() {
        var layoutHeight = layoutHeightPx();
        var visibleHeight = visibleHeightPx();
        return layoutHeight > 0 && visibleHeight > 0 && visibleHeight < layoutHeight * 0.85;
    }

    function widgetSelectors() {
        return [
            '#psn-widget-content-frame',
            '.widget-content-container',
            '#psn-widget-content-frame.mobile-full-page',
            '.widget-content-container.mobile-full-page'
        ];
    }

    function resetWidgetHeights() {
        widgetSelectors().forEach(function(selector) {
            document.querySelectorAll(selector).forEach(function(el) {
                el.style.removeProperty('height');
                el.style.removeProperty('max-height');
                el.style.removeProperty('min-height');
            });
        });
    }

    function ensureInternalScroll() {
        document.querySelectorAll('.widget-content-container, .widget-content').forEach(function(el) {
            el.style.setProperty('overflow-y', 'auto', 'important');
            el.style.setProperty('-webkit-overflow-scrolling', 'touch', 'important');
            el.style.setProperty('touch-action', 'pan-y', 'important');
        });
    }

    function applyLayout() {
        if (!document.getElementById('psn-widget-content-frame')) {
            return;
        }

        ensureInternalScroll();

        if (!isKeyboardOpen()) {
            resetWidgetHeights();
            return;
        }

        var heightPx = visibleHeightPx() + 'px';
        ['#psn-widget-content-frame', '.widget-content-container'].forEach(function(selector) {
            document.querySelectorAll(selector).forEach(function(el) {
                el.style.setProperty('height', heightPx, 'important');
                el.style.setProperty('max-height', heightPx, 'important');
            });
        });
    }

    window.__pisanoApplyViewportLayout = applyLayout;

    if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', applyLayout);
        window.visualViewport.addEventListener('scroll', applyLayout);
    }
    window.addEventListener('resize', applyLayout);
    document.addEventListener('focusin', function(event) {
        var tag = event.target && event.target.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') {
            setTimeout(applyLayout, 50);
            setTimeout(applyLayout, 250);
        }
    });
    document.addEventListener('focusout', function() {
        setTimeout(applyLayout, 50);
        setTimeout(applyLayout, 250);
    });
})();"
